package mod.cdv.tnpc.tactical;
import fixture.*;import java.util.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.item.ItemStack;import net.minecraft.world.entity.EquipmentSlot;import mod.cdv.tnpc.entity.AutoGunOperator;import dev.zomboid.clans.Companions16;import me.danialisntcool.factionfriction.data.FactionManager;import net.minecraft.nbt.CompoundTag;
public class SocialChecks{
 static int checks;static void ok(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}static AutoGunOperator npc(World w,int kind)throws Exception{AutoGunOperator n=new AutoGunOperator(w);n.setItemSlot(EquipmentSlot.MAINHAND,new ItemStack("tacz:gun",1));Social.init(n);n.tag.putInt("soc_kind",kind);return n;}
 static void acquire(AutoGunOperator n,long tick)throws Exception{n.w.now=tick;Social.acquire(n,CalmBrain.state(n),tick,true);}
 public static class Source{Object player;Source(Object p){player=p;}public String getMsgId(){return "player";}public Object getEntity(){return player;}public Object getDirectEntity(){return null;}}
 static void faction(World w,Player p,AutoGunOperator n){FactionManager.Faction f=new FactionManager.Faction();w.server.manager.factions.put(f.id,f);w.server.manager.playerFaction.put(p.uuid,f.id);ok(!Companions16.enroll(w.server,n.uuid,p,"Sam").isEmpty(),"real companion roster enrollment");}
 public static void main(String[] a)throws Exception{
  for(int k=0;k<3;k++)for(boolean armed:new boolean[]{false,true})for(boolean ally:new boolean[]{false,true})for(int reputation:new int[]{-100,-60,-30,0,60})for(int ticks:new int[]{0,99,100,200}){boolean attack=SocialRules.attack(k,armed,ally,false,0,reputation,ticks);ok(attack==(k==0&&armed&&!ally&&reputation>-60&&ticks>=100),"disposition/weapon/inspection/fear policy");}
  ok(SocialRules.recruit(0,0,-60,true),"intimidated armed hostile can be recruited");ok(!SocialRules.recruit(2,40,-50,false)&&SocialRules.recruit(2,75,-50,false),"bad reputation makes peaceful persuasion harder");ok(!SocialRules.recruit(1,44,0,true)&&SocialRules.recruit(1,45,0,true),"neutral trust threshold");
  World w=new World();AutoGunOperator hostile=npc(w,0);Player p=new Player(w);p.x=4;acquire(hostile,0);for(int tick=10;tick<100;tick+=10){acquire(hostile,tick);ok(hostile.target==null,"no shot target during five second inspection");}acquire(hostile,100);ok(hostile.target==p,"hostile acquires at five seconds");ok(!Social.blockPlayerAttack(hostile,p),"guard allows inspected hostile fire");p.visible=false;acquire(hostile,110);ok(Social.blockPlayerAttack(hostile,p),"line of sight required at firing time");p.visible=true;acquire(hostile,200);ok(hostile.target==null,"inspection resets after interrupted visibility");for(int tick=210;tick<=300;tick+=10)acquire(hostile,tick);ok(hostile.target==p,"inspection resumes after full new interval");
  hostile.setItemSlot(EquipmentSlot.MAINHAND,ItemStack.EMPTY);acquire(hostile,310);ok(hostile.target==null&&Social.blockPlayerAttack(hostile,p),"disarmed hostile cannot attack");
  World normalWorld=new World();AutoGunOperator neutral=npc(normalWorld,1);Player q=new Player(normalWorld);q.x=3;acquire(neutral,0);acquire(neutral,300);ok(neutral.target==null,"neutral does not attack first");NpcMedicine.init(neutral);neutral.tag.putDouble("np15_hp_body",12);Social.hurt(neutral,new Source(q),2,true);acquire(neutral,310);ok(neutral.target==q,"neutral retaliates after accepted attack");ok(Social.trust(neutral,q)==-30&&Social.rep(q)==-8,"harm changes persistent local and global reputation");
  neutral.tag.putInt("soc_kind",2);acquire(neutral,320);ok(neutral.target==q&&!Social.blockPlayerAttack(neutral,q),"passive defends itself after accepted attack");
  World allyWorld=new World();AutoGunOperator ally=npc(allyWorld,0);Player owner=new Player(allyWorld);owner.x=2;faction(allyWorld,owner,ally);acquire(ally,0);acquire(ally,200);ok(ally.target==null&&SocialRules.attack(0,true,true,true,-100,0,999),"faction friendliness survives hostile disposition");ok(Boolean.TRUE.equals(Social.allied(ally,owner)),"native alliance bridge");
  Companions16.change(allyWorld.server,owner.uuid,-999);ok(Companions16.reputation(allyWorld.server,owner.uuid)==-100,"reputation lower bound");Companions16.change(allyWorld.server,owner.uuid,999);ok(Companions16.reputation(allyWorld.server,owner.uuid)==100,"reputation upper bound");CompoundTag save=new CompoundTag();Companions16.save(allyWorld.server.manager,save);FactionManager restored=new FactionManager();restored.factions.putAll(allyWorld.server.manager.factions);restored.playerFaction.putAll(allyWorld.server.manager.playerFaction);Companions16.load(restored,save);allyWorld.server.manager=restored;ok(Companions16.member(allyWorld.server,owner,ally.uuid)&&Companions16.reputation(allyWorld.server,owner.uuid)==100,"roster and reputation survive save/load");Companions16.remove(allyWorld.server,ally.uuid);ok(!Companions16.member(allyWorld.server,owner,ally.uuid),"death/dismissal removes companion");
  World craftWorld=new World();craftWorld.blocks.put(new net.minecraft.core.BlockPos(0,0,1),"minecraft:crafting_table");AutoGunOperator crafter=npc(craftWorld,1);crafter.bag.add(new ItemStack("minecraft:wheat",2));ok(!Tasks.craft(crafter)&&crafter.bag.get(0).count==2,"cannot craft without materials");crafter.bag.get(0).count=3;craftWorld.recipes.enabled=false;ok(!Tasks.craft(crafter)&&crafter.bag.get(0).count==3,"actual recipe validation required");craftWorld.recipes.enabled=true;ok(Tasks.craft(crafter),"crafts with valid recipe");ok(crafter.bag.size()==1&&crafter.bag.get(0).id.equals("minecraft:bread")&&crafter.bag.get(0).count==1,"three wheat consumed for actual bread output");
  crafter.bag.clear();crafter.bag.add(new ItemStack("minecraft:coal",3));CompanionInventory inv=new CompanionInventory(crafter,owner);ok(inv.getItem(0).count==3,"live inventory shows bag");inv.setItem(0,ItemStack.EMPTY);ok(crafter.bag.isEmpty(),"taking stack immediately removes persistent cargo");ItemStack helmet=new ItemStack("minecraft:iron_helmet",1);ok(inv.canPlaceItem(47,helmet)&&!inv.canPlaceItem(47,new ItemStack("minecraft:bread",1)),"armor slot validation");inv.setItem(47,helmet);ok(crafter.getItemBySlot(EquipmentSlot.HEAD)==helmet,"helmet slot changes actual equipped item");ok(!inv.canPlaceItem(53,helmet),"reserved slot rejects items");
  World talkWorld=new World();AutoGunOperator talker=npc(talkWorld,2);Player friend=new Player(talkWorld);friend.x=2;Object result=Conversation.interact(talker,friend,net.minecraft.world.InteractionHand.MAIN_HAND);ok(result!=null&&TalkNetwork.last.split("\n").length==16,"right click opens server-generated conversation snapshot");ok(Conversation.action(friend,"greet")==1,"valid nearby dialogue action");int trust=Social.trust(talker,friend);Conversation.action(friend,"greet");ok(Social.trust(talker,friend)==trust,"click flood cannot farm trust");talkWorld.now=20;Conversation.action(friend,"greet");ok(Social.trust(talker,friend)==trust,"topic cooldown prevents repeated trust gain");friend.x=100;talkWorld.now=40;ok(Conversation.action(friend,"invite")==0,"remote action rejected");
  System.out.println("NPC_SOCIAL_WORLD_CHECKS="+checks);
 }
}
